for (const [ru, en] of P) {
  if (!s.includes(ru)) { console.error('нет русской строки:\n  ' + ru.slice(0, 140)); process.exit(1); }
  s = s.split(ru).join(en);
}
/* строка городов — как на живой английской главной */
const live = fs.readFileSync(path.join(site, 'en/index.html'), 'utf8');
const cities = /<p>Prayer times: [\s\S]*?<\/p>/.exec(live);
s = s.replace('__CITIES__', cities ? cities[0] : '');
/* комментарии вёрстки остаются русскими — их вырезаем, кириллица допустима только в ссылке «RU» */
s = s.replace(/<!--[\s\S]*?-->\n?/g, '');
const left = s.replace('Читать по-русски', '').match(/[А-Яа-яЁё][^<>"]{0,60}/g);
if (left) { console.error('осталась кириллица:\n  ' + [...new Set(left)].slice(0, 30).join('\n  ')); process.exit(1); }
fs.mkdirSync(path.join(site, 'v4/en'), { recursive: true });
fs.writeFileSync(path.join(site, 'v4/en/index.html'), s);
console.log('v4/en/index.html', Math.round(s.length / 1024), 'КБ');
